324	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
325	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
326		for id, c := range s.campaigns {
327			if id == excludeCampaign || c.Ended {
328				continue
329			}
330			if _, ok := c.index[deviceID]; ok {
331				return true
332			}
333		}
334		return false
335	}
336	
337	func operationID(campaignID, deviceID, stage string) string {
338		return campaignID + ":" + deviceID + ":" + stage
339	}
340	
341	func containsString(list []string, v string) bool {
342		for _, x := range list {
343			if x == v {
344				return true
345			}
346		}
347		return false
348	}
