		CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
		At: lateAt, Success: true,
		Seq: 2, Version: "v2", Config: json.RawMessage(`{}`),
	}); !errors.Is(err, ErrCampaignEnded) {
